sieve-archive-all.contents:
require ["fileinto", "copy", "mailbox", "special-use", "imap4flags", "spamtest", "relational", "comparator-i;ascii-numeric"];

# Spam goes to Junk and is deliberately NOT copied to the archive, so emptying Junk
# actually frees it. This branch is also load-bearing: Stalwart's own spam filing at
# ingest.rs:357 is guarded by `mailbox_ids == [INBOX_ID]`, an exact vector equality, and
# any fileinto below would break that equality and silently deliver spam to the Inbox.
# The threshold reproduces Stalwart's decision exactly -- is_spam() is
# `spam_percentage >= 50`, and spam_status() maps Ham to 1, MaybeSpam(pct) to
# ((pct*10) as i64).clamp(2,9), Spam to 10, Unknown to 0. So 49 -> 4 and 50 -> 5.
if spamtest :value "ge" :comparator "i;ascii-numeric" "5" {
    addflag "$Junk";
    fileinto "Junk";
} else {
    # Targeted by SPECIAL-USE rather than by name: whatever mailbox carries \\Archive
    # receives the copy, so renaming the folder -- or a user who named theirs something
    # else -- cannot silently break this. "Archive" is only the fallback name used when
    # :create has to make it.
    #
    # :copy leaves the implicit keep intact, so the message lands in BOTH Inbox and the
    # archive. That is one message in two mailboxes, not two copies: ingest takes a Vec of
    # mailbox ids on a single document, verified live as mailboxId = [9, 0]. Deleting from
    # the Inbox, or iOS purging Trash after its default seven days, only untags one mailbox
    # -- expunge.rs destroys a message solely when mailboxes.len() == 1.
    fileinto :copy :specialuse "\\Archive" :create "Archive";
}
